import{_ as d,o as e,c as o,a6 as a}from"./chunks/framework.BrkgobfX.js";const E=JSON.parse('{"title":"HTTP/3 帧格式","description":"变长帧头、七种帧类型、四类单向流，以及被删除的 h2 帧。","frontmatter":{"title":"HTTP/3 帧格式","description":"变长帧头、七种帧类型、四类单向流，以及被删除的 h2 帧。","source":"https://daiw.org/manual/http2-3/h3-framing"},"headers":[],"relativePath":"manual/computer-programming/http2-3/h3-framing.md","filePath":"manual/computer-programming/http2-3/h3-framing.md"}'),n={name:"manual/computer-programming/http2-3/h3-framing.md"};function r(s,t,c,p,l,h){return e(),o("div",null,[...t[0]||(t[0]=[a(`<h1 id="http-3-帧格式" tabindex="-1">HTTP/3 帧格式 <a class="header-anchor" href="#http-3-帧格式" aria-label="Permalink to &quot;HTTP/3 帧格式&quot;">​</a></h1><p>变长帧头、七种帧类型、四类单向流，以及被删除的 h2 帧。</p><h2 id="帧格式" tabindex="-1">帧格式 <a class="header-anchor" href="#帧格式" aria-label="Permalink to &quot;帧格式&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>HTTP/3 Frame {</span></span>
<span class="line"><span>  Type   (变长整数),</span></span>
<span class="line"><span>  Length (变长整数),</span></span>
<span class="line"><span>  Frame Payload (..),</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>对照 <a href="/Front2Full/manual/computer-programming/http2-3/h2-framing">h2 的 9 字节定长头</a>，三处差异：</p><table tabindex="0"><thead><tr><th></th><th>h2</th><th>h3</th></tr></thead><tbody><tr><td>头部长度</td><td><strong>固定 9 字节</strong></td><td><strong>通常 2 字节</strong>（变长）</td></tr><tr><td>流 ID</td><td><strong>在帧头里</strong></td><td><strong>不在</strong>——由 QUIC 流承载</td></tr><tr><td>标志位</td><td>8 位 Flags</td><td><strong>无</strong>——语义改由帧类型或 QUIC 表达</td></tr></tbody></table><p>h3 帧头不含流 ID，因为<strong>帧已经写在某条 QUIC 流上了</strong>，流身份由传输层提供。同理 <code>END_STREAM</code> 标志也没了——改用 QUIC 的流 FIN 位。</p><h2 id="七种帧类型" tabindex="-1">七种帧类型 <a class="header-anchor" href="#七种帧类型" aria-label="Permalink to &quot;七种帧类型&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Type</th><th>名称</th><th>允许出现在</th></tr></thead><tbody><tr><td><code>0x00</code></td><td><code>DATA</code></td><td>请求流</td></tr><tr><td><code>0x01</code></td><td><code>HEADERS</code></td><td>请求流、推送流</td></tr><tr><td><code>0x03</code></td><td><code>CANCEL_PUSH</code></td><td>控制流</td></tr><tr><td><code>0x04</code></td><td><code>SETTINGS</code></td><td>控制流（<strong>必须是首帧</strong>）</td></tr><tr><td><code>0x05</code></td><td><code>PUSH_PROMISE</code></td><td>请求流</td></tr><tr><td><code>0x07</code></td><td><code>GOAWAY</code></td><td>控制流</td></tr><tr><td><code>0x0d</code></td><td><code>MAX_PUSH_ID</code></td><td>控制流</td></tr></tbody></table><p><strong>未知帧类型 MUST 被忽略</strong>（扩展点，同 h2）。</p><h2 id="被删除的-h2-帧" tabindex="-1">被删除的 h2 帧 <a class="header-anchor" href="#被删除的-h2-帧" aria-label="Permalink to &quot;被删除的 h2 帧&quot;">​</a></h2><p>这些帧类型在 h3 中<strong>被永久保留为非法</strong>——收到即 <code>H3_FRAME_UNEXPECTED</code>：</p><table tabindex="0"><thead><tr><th>h2 帧</th><th>类型值</th><th>为什么没了</th></tr></thead><tbody><tr><td><code>PRIORITY</code></td><td><code>0x02</code></td><td>优先级树<a href="/Front2Full/manual/computer-programming/http2-3/h2-settings-priority">已废弃</a>，改用 <code>priority</code> 字段</td></tr><tr><td><code>PING</code></td><td><code>0x06</code></td><td>QUIC 有 <code>PING</code> 帧</td></tr><tr><td><code>WINDOW_UPDATE</code></td><td><code>0x08</code></td><td>QUIC 有 <code>MAX_DATA</code>/<code>MAX_STREAM_DATA</code></td></tr><tr><td><code>CONTINUATION</code></td><td><code>0x09</code></td><td><strong>不再需要</strong>——见下</td></tr><tr><td><code>RST_STREAM</code></td><td>—</td><td>QUIC 有 <code>RESET_STREAM</code> 帧</td></tr></tbody></table><p>保留这些值而非复用，是为了让「h2 帧被误发到 h3 连接上」这种协议混淆能被<strong>立即检出</strong>。</p><h3 id="continuation-消失的意义" tabindex="-1">CONTINUATION 消失的意义 <a class="header-anchor" href="#continuation-消失的意义" aria-label="Permalink to &quot;CONTINUATION 消失的意义&quot;">​</a></h3><p>h2 中字段块超过 <code>MAX_FRAME_SIZE</code> 就要拆成 <code>HEADERS</code> + 若干 <code>CONTINUATION</code>，且<a href="/Front2Full/manual/computer-programming/http2-3/h2-framing">中间不得插入任何其他帧</a>——巨大的头部会短暂<strong>独占整条连接</strong>。</p><p>h3 的 <code>HEADERS</code> 帧长度是<strong>变长整数</strong>（上限 2^62−1），一个帧就能装下任意大的字段块；而且它写在自己的 QUIC 流上，天然不影响其他流。<strong>CONTINUATION Flood 这类攻击面在 h3 上不存在。</strong></p><h2 id="四类单向流" tabindex="-1">四类单向流 <a class="header-anchor" href="#四类单向流" aria-label="Permalink to &quot;四类单向流&quot;">​</a></h2><p>h3 用 QUIC 的<strong>单向流</strong>承载连接级信令。每条单向流的<strong>第一个变长整数是流类型</strong>：</p><table tabindex="0"><thead><tr><th>流类型</th><th>名称</th><th>作用</th></tr></thead><tbody><tr><td><code>0x00</code></td><td><strong>控制流</strong></td><td><code>SETTINGS</code>、<code>GOAWAY</code>、<code>MAX_PUSH_ID</code>、<code>CANCEL_PUSH</code></td></tr><tr><td><code>0x01</code></td><td>推送流</td><td>服务端推送的响应（已无实际使用）</td></tr><tr><td><code>0x02</code></td><td><strong>QPACK 编码器流</strong></td><td><a href="/Front2Full/manual/computer-programming/http2-3/qpack">动态表</a>插入指令</td></tr><tr><td><code>0x03</code></td><td><strong>QPACK 解码器流</strong></td><td>确认与取消指令</td></tr></tbody></table><p>规则：</p><ul><li>双方<strong>各 MUST 开一条控制流</strong>，且<strong>在连接早期开启</strong>。</li><li>控制流上的<strong>首帧 MUST 是 <code>SETTINGS</code></strong>，否则 <code>H3_MISSING_SETTINGS</code>。</li><li>控制流、QPACK 两条流<strong>每种只能有一条</strong>，重复开启 → <code>H3_STREAM_CREATION_ERROR</code>。</li><li>这些流<strong>MUST NOT 被关闭</strong>。关闭任何一条 → <code>H3_CLOSED_CRITICAL_STREAM</code>，整条连接终止。</li><li>未知流类型 <strong>MUST</strong> 被忽略（可安全地停止读取）。</li></ul><p>对照 h2：h2 用<strong>流 0</strong> 承载所有连接级帧；h3 没有流 0，改用专门的单向流——因为 QUIC 的流 ID 空间里没有「0 号连接级流」这个概念。</p><h2 id="没有连接前言" tabindex="-1">没有连接前言 <a class="header-anchor" href="#没有连接前言" aria-label="Permalink to &quot;没有连接前言&quot;">​</a></h2><p>h2 有 24 字节的 <a href="/Front2Full/manual/computer-programming/http2-3/h2-connection"><code>PRI * HTTP/2.0</code> 魔数</a>，用于防止把 h2 帧发给 1.1 服务端。</p><p>h3 <strong>不需要</strong>：ALPN 在 QUIC 握手中已经确定了协议是 <code>h3</code>，且 QUIC 本身与 TCP 不兼容，不存在「误发给 1.1 服务端」的可能。取而代之的是「控制流首帧必须是 <code>SETTINGS</code>」这一约定。</p><h2 id="settings" tabindex="-1">SETTINGS <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;SETTINGS&quot;">​</a></h2><p>同样是单向声明 + 不可重发，但与 h2 有三点不同：</p><table tabindex="0"><thead><tr><th></th><th>h2</th><th>h3</th></tr></thead><tbody><tr><td>承载</td><td>流 0 的 <code>SETTINGS</code> 帧</td><td><strong>控制流首帧</strong></td></tr><tr><td>是否需 ACK</td><td><strong>需要</strong>（<code>ACK</code> 标志）</td><td><strong>不需要</strong></td></tr><tr><td>可否重发</td><td>可以，随时更新</td><td><strong>不可</strong>——一条连接只发一次，再发 → <code>H3_FRAME_UNEXPECTED</code></td></tr></tbody></table><p>h3 的三个标准参数：</p><table tabindex="0"><thead><tr><th>ID</th><th>名称</th><th>作用</th></tr></thead><tbody><tr><td><code>0x01</code></td><td><code>QPACK_MAX_TABLE_CAPACITY</code></td><td>QPACK 动态表容量，默认 <strong>0</strong>（即默认禁用动态表）</td></tr><tr><td><code>0x06</code></td><td><code>MAX_FIELD_SECTION_SIZE</code></td><td>字段列表未压缩大小上限（对应 h2 的 <code>MAX_HEADER_LIST_SIZE</code>）</td></tr><tr><td><code>0x07</code></td><td><code>QPACK_BLOCKED_STREAMS</code></td><td>允许因 QPACK 而阻塞的最大流数，默认 <strong>0</strong></td></tr></tbody></table><p>注意 h2 的 <code>INITIAL_WINDOW_SIZE</code>、<code>MAX_CONCURRENT_STREAMS</code>、<code>MAX_FRAME_SIZE</code> 在 h3 中<strong>都不存在</strong>——分别由 QUIC 的传输参数 <code>initial_max_stream_data_*</code>、<code>initial_max_streams_bidi</code> 承担，帧大小则无需限制。</p><h2 id="请求流的帧序列" tabindex="-1">请求流的帧序列 <a class="header-anchor" href="#请求流的帧序列" aria-label="Permalink to &quot;请求流的帧序列&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>客户端在一条双向流上:</span></span>
<span class="line"><span>  HEADERS                 请求头(QPACK 编码)</span></span>
<span class="line"><span>  DATA (可选，可多个)      请求体</span></span>
<span class="line"><span>  HEADERS (可选)          trailer 字段</span></span>
<span class="line"><span>  → QUIC 流 FIN 位        相当于 h2 的 END_STREAM</span></span>
<span class="line"><span></span></span>
<span class="line"><span>服务端在同一条流上:</span></span>
<span class="line"><span>  HEADERS (可选，多个)     1xx 中间响应</span></span>
<span class="line"><span>  HEADERS                 最终响应头</span></span>
<span class="line"><span>  DATA (可选，可多个)      响应体</span></span>
<span class="line"><span>  HEADERS (可选)          trailer</span></span>
<span class="line"><span>  → QUIC 流 FIN 位</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br></div></div><p>约束：</p><ul><li>请求流上<strong>必须</strong>恰好有一个请求与一个最终响应。</li><li>客户端流上收到 <code>DATA</code> 而无先行 <code>HEADERS</code> → <code>H3_FRAME_UNEXPECTED</code>。</li><li>请求流未完整（缺响应就 FIN）→ <code>H3_REQUEST_INCOMPLETE</code>。</li></ul><h2 id="错误码" tabindex="-1">错误码 <a class="header-anchor" href="#错误码" aria-label="Permalink to &quot;错误码&quot;">​</a></h2><p>h3 错误码从 <code>0x0100</code> 起，与 QUIC 传输层错误码共用同一空间但不重叠：</p><table tabindex="0"><thead><tr><th>码</th><th>名称</th><th>触发</th></tr></thead><tbody><tr><td><code>0x0100</code></td><td><code>H3_NO_ERROR</code></td><td>正常关闭</td></tr><tr><td><code>0x0101</code></td><td><code>H3_GENERAL_PROTOCOL_ERROR</code></td><td>未归类的协议违规</td></tr><tr><td><code>0x0102</code></td><td><code>H3_INTERNAL_ERROR</code></td><td>实现内部错误</td></tr><tr><td><code>0x0103</code></td><td><code>H3_STREAM_CREATION_ERROR</code></td><td>流创建违规（如重复控制流）</td></tr><tr><td><code>0x0104</code></td><td><code>H3_CLOSED_CRITICAL_STREAM</code></td><td>关键流被关闭</td></tr><tr><td><code>0x0105</code></td><td><code>H3_FRAME_UNEXPECTED</code></td><td>帧出现在不允许的位置</td></tr><tr><td><code>0x0106</code></td><td><code>H3_FRAME_ERROR</code></td><td>帧格式或长度错</td></tr><tr><td><code>0x0107</code></td><td><code>H3_EXCESSIVE_LOAD</code></td><td>对端负载过大（对应 h2 的 <code>ENHANCE_YOUR_CALM</code>）</td></tr><tr><td><code>0x0109</code></td><td><code>H3_SETTINGS_ERROR</code></td><td>SETTINGS 违规</td></tr><tr><td><code>0x010a</code></td><td><code>H3_MISSING_SETTINGS</code></td><td>控制流首帧不是 SETTINGS</td></tr><tr><td><code>0x010b</code></td><td><code>H3_REQUEST_REJECTED</code></td><td><strong>未处理</strong>即拒绝，客户端可安全重试（对应 <code>REFUSED_STREAM</code>）</td></tr><tr><td><code>0x010c</code></td><td><code>H3_REQUEST_CANCELLED</code></td><td>请求被取消</td></tr><tr><td><code>0x010e</code></td><td><code>H3_MESSAGE_ERROR</code></td><td>消息 malformed（如伪头违规）</td></tr><tr><td><code>0x0110</code></td><td><code>H3_VERSION_FALLBACK</code></td><td>要求客户端改用 HTTP/1.1 重试</td></tr></tbody></table><p>下一篇：<a href="/Front2Full/manual/computer-programming/http2-3/qpack">QPACK 头部压缩</a>。</p>`,40)])])}const g=d(n,[["render",r]]);export{E as __pageData,g as default};
